mStatus,el.colourargb\r\n\t\t,e.dateoftest,a.startdate,e.[filename] AS classlocation\r\nFROM\texams e LEFT JOIN Appointments a ON a.examid=e.examid \r\n        LEFT JOIN people pwho ON pwho.personid=a.personid\r\n\t\tLEFT JOIN AppointmentTypes at ON at.AppTypeID=a.apptypeid\r\n\r\n\t\tLEFT JOIN attendees att ON att.AppointmentID=a.AppointmentID \r\n\t\tLEFT JOIN people p ON p.personid=att.personid \r\n\t\tLEFT JOIN PeopleGroups pg ON pg.PersonID=att.PersonID AND pg.GroupID<5 \r\n\r\n\t\tLEFT JOIN AppointmentCourses ac ON ac.AppointmentID=a.appointmentid\r\n\r\n\t\tLEFT JOIN LUCourses luc ON luc.LUCourseID=ac.lucourseid\r\n\t\tLEFT JOIN LUCourseData lucd ON lucd.luCourseDataID=luc.subjectid\r\n\t\tLEFT JOIN Courses c ON c.personID=p.PersonID AND c.luCourseID=luc.lucourseid\r\n\r\n\t\tLEFT JOIN AppointmentsLastDateModified amd ON amd.AppointmentId=a.AppointmentID\r\n\t\tLEFT JOIN (SELECT DISTINCT personid,MAX(dateentered) AS maxdateentered FROM accommodationsapproval GROUP BY personid) aa ON aa.personid=p.PersonID AND aa.maxdateentered>amd.DateLastModified\r\n        LEFT JOIN ExamStatusLookup el ON el.ExamStatusLookupId=ac.ExamStatusLookupId\r\nWHERE\t(a.startdate BETWEEN @startdate AND @enddate ) \r\n        AND NOT a.AppointmentID IS NULL \r\n\t\tAND NOT pg.personid IS NULL \r\n\t\tAND (NOT a.appointmentid IS NULL) \r\n        AND (@allowcancelled=1 OR a.cancelled=0)\r\nORDER BY a.AppointmentID,e.examid,att.personid ";

